mapper.select:
select wms_tasks.task_type, count(*) as taskCount
from wms_tasks
where
    1 = 1


        and task_status = #{taskStatus}



        and target_warehouse_id = #{targetWarehouseId}



        and source_warehouse_id = #{sourceWarehouseId}



        and DATE(create_time) = DATE(#{createTimeString})

group by wms_tasks.task_type

-- 修正写法：外层再处理显示格式，1055报错彻底消失 SELECT SUBSTRING(t.name, 6, 2) AS name -- 从 '2025-09' 里截出 '09' -- 要"月"字就用这个：CONCAT(SUBSTRING(t.name, 6, 2), '月') AS name , t.value AS value FROM ( -- 内层：老老实实按 %Y-%m 分组（保证数据正确、不跨年合并） SELECT DATE_FORMAT(o.create_time, '%Y-%m') AS name, IFNULL(SUM(o.total_shelved_quantity), 0) AS value FROM wms_stock_in_orders o WHERE 1 = 1 -- 查询仓库id
AND o.warehouse_id = #{warehouseId}
AND o.status = 'PUTAWAYED' AND o.create_time >= DATE_SUB(CURDATE(), INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(o.create_time, '%Y-%m') ORDER BY DATE_FORMAT(o.create_time, '%Y-%m') ASC ) t;

SELECT SUBSTRING(t.name, 6, 2) AS name -- 从 '2025-09' 里截出 '09' -- 要"月"字就用这个：CONCAT(SUBSTRING(t.name, 6, 2), '月') AS name , t.value AS value FROM ( -- 内层：老老实实按 %Y-%m 分组（保证数据正确、不跨年合并） SELECT DATE_FORMAT(o.create_time, '%Y-%m') AS name, IFNULL(SUM(o.total_quantity), 0) AS value FROM wms_out_orders o WHERE 1 = 1 -- 查询仓库id
AND o.warehouse_id = #{warehouseId}
AND o.status = 'PACKED' AND o.create_time >= DATE_SUB(CURDATE(), INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(o.create_time, '%Y-%m') ORDER BY DATE_FORMAT(o.create_time, '%Y-%m') ASC ) t;
